import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BvlN9b-o.js";const p=JSON.parse('{"title":"Rust 公共接入地图","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/reference/rust","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"reference/rust.md","filePath":"reference/rust.md"}'),c={name:"reference/rust.md"};function d(s,e,b,f,l,n){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="rust-公共接入地图" tabindex="-1">Rust 公共接入地图 <a class="header-anchor" href="#rust-公共接入地图" aria-label="Permalink to &quot;Rust 公共接入地图&quot;">​</a></h1><p>这页面向正在编写自己业务模块的后端开发者。HTTP DTO 在 <a href="./api">API 参考</a> 查阅；Rust 函数的完整签名和内部限制以链接源码为准。先完成 <a href="./../guides/new-module">新增后端模块</a>，再按需要接入下表。</p><p><code>saas_app</code> 提供 SaaS Core 与 HTTP 边界，<code>saas_platform</code> 提供配置和基础设施适配。业务模块调用这些公开能力；API 与 Worker 在应用侧显式组装。当前企业模型是单个 Organization，不支持把不同客户的数据放进同一数据库后自动隔离。</p><h2 id="http-与身份" tabindex="-1">HTTP 与身份 <a class="header-anchor" href="#http-与身份" aria-label="Permalink to &quot;HTTP 与身份&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公开入口</th><th>调用上下文</th><th>返回值或错误</th><th>责任与限制</th><th>受检查用法</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/lib.rs" target="_blank" rel="noreferrer"><code>compose_routes_with_options</code></a> / <code>CoreOptions</code></td><td>应用启动：连接池、认证配置、业务 Router、合并 OpenAPI</td><td>Axum <code>Router</code></td><td>提供 Core 路由、request_id、限流和统一 fallback；先完成业务 state，再 merge</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/examples/tutorial-tickets/preview.rs" target="_blank" rel="noreferrer">第一阶段模块</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/health.rs" target="_blank" rel="noreferrer">HTTP 健康测试</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>BoundedJson</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>ApiQuery</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/http.rs" target="_blank" rel="noreferrer"><code>ApiPath</code></a></td><td>经过 Core request_context 的 Handler；JSON extractor 放最后</td><td>反序列化后的 DTO；失败为公开 <code>Response</code></td><td>只负责协议读取；长度和业务规则继续由 Domain 验证</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/registration.rs" target="_blank" rel="noreferrer">身份 HTTP 测试</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>require_session</code></a></td><td>连接池、<code>AuthSettings</code>、请求头、<code>RequestId</code>、是否 mutation</td><td><code>Result&lt;CurrentSession, Response&gt;</code></td><td>mutation 校验 Origin/CSRF；显式 Authorization 不会退回 Cookie；写事务仍须重新锁定有效成员</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/sessions.rs" target="_blank" rel="noreferrer">Session HTTP 测试</a>、<a href="./../tutorials/sessions">Session 接入</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/api_keys/authentication.rs" target="_blank" rel="noreferrer"><code>require_read</code></a></td><td>只读接口，额外传入业务注册的 scope</td><td><code>Result&lt;ReadActor, Response&gt;</code></td><td>Bearer 存在时优先；检查凭据、成员和 scope 后，业务继续检查资源权限</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/api_keys.rs" target="_blank" rel="noreferrer">API Key HTTP 测试</a>、API Key 接入</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/api_keys/mod.rs" target="_blank" rel="noreferrer"><code>KeyScope</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/api_keys/mod.rs" target="_blank" rel="noreferrer"><code>core_scopes</code></a></td><td>API 应用组装</td><td>scope 声明 / Core scope 列表</td><td>把业务只读 scope 添加到 CoreOptions；scope 不等于资源授权</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/src/lib.rs" target="_blank" rel="noreferrer">API 组装点</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>background_credential</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer"><code>credential_is_current</code></a></td><td>已授权 actor 的请求事务 / Worker 发布事务</td><td><code>Option&lt;CredentialRef&gt;</code> / <code>bool</code>，数据库错误</td><td>持久化凭据引用，不保存 Cookie；Worker 检查不会延长原凭据寿命</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/sessions.rs" target="_blank" rel="noreferrer">凭据行为测试</a></td></tr></tbody></table><p><code>require_session</code> 返回身份，不替代工单、账单等资源规则。业务应在自己的用例里验证当前访问资格，避免先检查权限、随后在另一个事务中写入造成竞态。</p><h2 id="调用者拥有的数据库事务" tabindex="-1">调用者拥有的数据库事务 <a class="header-anchor" href="#调用者拥有的数据库事务" aria-label="Permalink to &quot;调用者拥有的数据库事务&quot;">​</a></h2><p>下列入口接受 <code>&amp;mut PgConnection</code>。传入同一个 <code>&amp;mut *tx</code>，检查每一步的结果，最后由业务用例提交；不要先提交业务再补审计或任务。</p><table tabindex="0"><thead><tr><th>公开入口</th><th>输入 / 输出</th><th>错误</th><th>事务责任</th><th>受检查用法</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer"><code>enroll</code></a></td><td>新用户 id → <code>MemberRole</code></td><td><code>sqlx::Error</code></td><td>账号创建事务中加入当前企业；首位 Owner 通过组织行串行初始化</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/registration.rs" target="_blank" rel="noreferrer">注册事务测试</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer"><code>active_role_in</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer"><code>lock_memberships</code></a></td><td>user id / id 列表 → 当前成员角色 / 成员记录</td><td><code>sqlx::Error</code>；成员可能不存在或停用</td><td>写入前锁成员，再锁资源；多个成员按 id 顺序锁，维持与成员管理一致的顺序</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/membership_policy.rs" target="_blank" rel="noreferrer">成员并发测试</a>、<a href="./../tutorials/members">成员指南</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/audit/mod.rs" target="_blank" rel="noreferrer"><code>append</code></a> / <code>Event</code></td><td>actor、动作、资源和 <code>Source</code> → <code>()</code></td><td><code>sqlx::Error</code></td><td>与业务共用事务；失败回滚业务；元数据不能放任意请求 JSON 或秘密</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/audit.rs" target="_blank" rel="noreferrer">审计 HTTP 测试</a>、审计接入</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/idempotency/mod.rs" target="_blank" rel="noreferrer"><code>fingerprint</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/idempotency/mod.rs" target="_blank" rel="noreferrer"><code>claim</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/idempotency/mod.rs" target="_blank" rel="noreferrer"><code>complete</code></a></td><td><code>Attempt</code>：actor、scope、key、请求摘要 → 已有响应 / <code>()</code></td><td><code>InvalidKey</code>、<code>Conflict</code>、<code>Unavailable</code></td><td>先授权，再 claim；已有响应直接重放；新结果 complete 后提交，错误不留下业务或占位记录</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/examples/tutorial-tickets/application.rs" target="_blank" rel="noreferrer">工单幂等实现</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer"><code>enqueue</code></a> / <code>NewJob</code></td><td>kind、schema_version、业务 payload、尝试预算和关联信息 → Job id</td><td><code>sqlx::Error</code></td><td>与业务快照同一事务；kind 必须有 Worker Handler；payload 不放 token 或签名 URL</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/jobs.rs" target="_blank" rel="noreferrer">任务公开测试</a>、任务指南</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/notifications/mod.rs" target="_blank" rel="noreferrer"><code>on_job_outcome</code></a> / <code>JobNotification</code></td><td>Job id、recipient、稳定 event_key、通用 subject 和导航目标 → <code>()</code></td><td><code>sqlx::Error</code></td><td>与 enqueue 注册通知意图；Jobs 在终态事务发布；目标仍检查当前访问权限</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/notifications.rs" target="_blank" rel="noreferrer">通知 HTTP 测试</a>、通知指南</td></tr></tbody></table><h2 id="files-与-worker" tabindex="-1">Files 与 Worker <a class="header-anchor" href="#files-与-worker" aria-label="Permalink to &quot;Files 与 Worker&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公开入口</th><th>输入 / 输出</th><th>错误或限制</th><th>调用责任</th><th>受检查用法</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer"><code>FileService</code></a>：<code>start</code>、<code>upload_capability</code>、<code>plan_completion</code>、<code>verify_candidate</code>、<code>publish</code>、<code>download</code></td><td>上传登记 → 上传能力 → 完成计划 → 核验候选 → ready 文件 / 下载能力</td><td><code>files::Error</code>；对象可能缺失、变化、过期或核验失败</td><td>业务拥有附件归属和授权；对象 I/O 在短事务之外，核验后的发布与业务记录在同一事务</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/tests/object_storage.rs" target="_blank" rel="noreferrer">对象存储集成测试</a>、Files 接入</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/files/cleanup.rs" target="_blank" rel="noreferrer"><code>mark_deleting</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/files/cleanup.rs" target="_blank" rel="noreferrer"><code>cleanup_handler</code></a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/files/cleanup.rs" target="_blank" rel="noreferrer"><code>cleanup_maintenance</code></a></td><td>调用者事务的 File id / Worker 和维护注册</td><td>数据库或任务错误</td><td>先在事务撤销业务可见性，再异步清理对象；API 和 Worker 使用一致的存储设置</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/examples/tutorial-tickets/mod.rs" target="_blank" rel="noreferrer">课程源码</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer"><code>Handler</code></a> / <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer"><code>Worker</code></a></td><td><code>kind()</code> + <code>run(&amp;Lease)</code>；连接池、Handler 列表、<code>WorkerPolicy</code></td><td><code>Permanent</code>、<code>Transient</code>、<code>LostLease</code>；Worker 数据库错误</td><td>在 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/worker/src/main.rs" target="_blank" rel="noreferrer">Worker 组装点</a>显式注册；<code>run_once</code> 便于受控测试；<code>run_until</code> 负责有界停机</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/jobs.rs" target="_blank" rel="noreferrer">Job 集成测试</a>、恢复指南</td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer"><code>Lease</code></a>：<code>lock_current</code>、<code>succeed</code>、<code>heartbeat</code></td><td>当前租约 + 连接 / 连接池 → <code>()</code></td><td><code>JobError</code></td><td>修改结果前 lock_current，业务结果和 succeed 同一提交；失去租约后不能发布</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/jobs.rs" target="_blank" rel="noreferrer">Job 集成测试</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/mail/mod.rs" target="_blank" rel="noreferrer"><code>MailService</code></a>：<code>seal</code>、<code>open</code>、<code>send_plain_text</code></td><td>上下文绑定、受保护材料 / SMTP 文本</td><td><code>MaterialError</code>、传输错误；缺少配置时 from_env 返回 None</td><td>邮件秘密加密存储、按上下文绑定；调用者定义重试与一次性消费，不把正文写到日志</td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/mail_materials.rs" target="_blank" rel="noreferrer">邮件材料测试</a>、<a href="./../tutorials/password-reset">密码恢复</a></td></tr></tbody></table><h2 id="platform-与验证入口" tabindex="-1">Platform 与验证入口 <a class="header-anchor" href="#platform-与验证入口" aria-label="Permalink to &quot;Platform 与验证入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公开入口</th><th>返回 / 边界</th><th>使用指南</th></tr></thead><tbody><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/config.rs" target="_blank" rel="noreferrer"><code>Settings</code></a> / <code>from_env</code></td><td><code>Result&lt;Settings, ConfigError&gt;</code>；启动校验失败应退出</td><td><a href="./config">生成服务端配置</a>、<a href="./configuration-sources">变量来源</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/cache.rs" target="_blank" rel="noreferrer"><code>Cache</code></a>：<code>get</code>、<code>put</code>、<code>remove</code></td><td><code>Lookup</code>、<code>CacheUnavailable</code>；共享 deadline，不保证 Redis 可用</td><td>缓存接入、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/cache.rs" target="_blank" rel="noreferrer">真实缓存测试</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/rate_limit/mod.rs" target="_blank" rel="noreferrer"><code>RateLimiter</code></a></td><td>HTTP 请求预算；API 组装时共享实例</td><td><a href="./../tutorials/rate-limits">限流策略</a>、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/rate_limits.rs" target="_blank" rel="noreferrer">限流 HTTP 测试</a></td></tr><tr><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/platform/src/telemetry/mod.rs" target="_blank" rel="noreferrer"><code>init</code></a> / <code>TelemetryGuard</code></td><td>启动遥测；guard 在有界停机时 shutdown</td><td>日志与追踪、<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/telemetry_shutdown.rs" target="_blank" rel="noreferrer">关闭测试</a></td></tr></tbody></table><p>源码签名不是事务提交证明。编写自己的 <a href="./../testing/feedback-loop">HTTP 行为测试</a>，对拒绝、重放、回滚和租约失效验证可观察结果。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/examples/tutorial-tickets/application.rs" target="_blank" rel="noreferrer">工单用例源码</a>与 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/tests/tutorial_course.rs" target="_blank" rel="noreferrer">课程 HTTP 测试</a>展示自己业务的接入；模板所有权与移除边界见 <a href="./../architecture/boundaries">模块关系</a>。</p><p>完整参考业务的接入指南：<a href="./../tutorials/edit-conflicts">幂等与版本</a>、<a href="./../tutorials/attachments">Files</a>、<a href="./../tutorials/document-exports">Jobs</a>、<a href="./../tutorials/job-recovery">恢复</a>、<a href="./../tutorials/deletion-cleanup">删除</a>、<a href="./../tutorials/export-notifications">通知</a>、<a href="./../tutorials/audit-history">审计</a>、<a href="./../tutorials/api-keys">API Key</a>、<a href="./../tutorials/versioned-cache">缓存</a>、<a href="./../tutorials/observability">追踪</a>。这个参考业务阅读入口随知识库移除；共享能力指南继续保留。</p><hr><p>源码版本：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/reference/rust.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',17)])])}const u=a(c,[["render",d]]);export{p as __pageData,u as default};
